import itertools, sys

# literals representation: (var, sign) where sign True for positive, False for negated
vars_main = ['a','b','c']
fresh = ['x','y']
all_vars = vars_main + fresh

def literal(var, sign):
    return (var, sign)

def eval_lit(lit, assign):
    var, sign = lit
    val = assign[var]
    return val if sign else (not val)

def nae_clause_satisfied(clause, assign):
    vals = [eval_lit(l, assign) for l in clause]
    return not (all(vals) or not any(vals))  # not all true and not all false

def gadget_satisfiable(main_assign, clauses):
    # exists assignment to fresh vars making all clauses satisfied
    for fresh_assign in itertools.product([False, True], repeat=len(fresh)):
        assign = {v: main_assign[v] for v in vars_main}
        assign.update({fresh[i]: fresh_assign[i] for i in range(len(fresh))})
        if all(nae_clause_satisfied(cl, assign) for cl in clauses):
            return True
    return False

def find_gadget(max_clauses=3, max_fresh=2):
